func OptionalStringFromMap(in map[string]interface{}, name string,
	setFn func(v string),
) error {
	value, ok := in[name]
	if !ok {
		return nil  // Field not present = OK (optional)
	}

	asString, ok := value.(string)
	if !ok {
		return nil  // NOT A STRING = OK (silently ignores null/other types!)
	}

	setFn(asString)
	return nil
}

